export const WHO_LMS_SCALED = { height: { male: lhfa_boys, female: lhfa_girls }, weight: { male: wfa_boys, female: wfa_girls } } as const;
export function whoLmsAt(metric: 'height' | 'weight', sex: 'male' | 'female', ageDays: number): [number, number, number] | null {
    if (!Number.isInteger(ageDays) || ageDays < 0 || ageDays > 1856) return null;
    const values = WHO_LMS_SCALED[metric][sex], offset = ageDays * 3;
    return [values[offset]! / 10000, values[offset + 1]! / 10000, values[offset + 2]! / 100000];
}
